cat > candidate.mjs <<'EOF'
let source = "";
for await (const chunk of process.stdin) source += chunk;
const input = JSON.parse(source || "{}");

const json = { "content-type": "application/json" };
const { transferId, idempotencyKey, fromId, toId, amount, fromBalance, toBalance, fromVersion, toVersion } = input;

function accounts(from, to, fv, tv) {
  return [{ id: fromId, balance: from, version: fv }, { id: toId, balance: to, version: tv }];
}

function result({ status, body, from, to, committed, messages = [], ordering = [], failures = [], retryable = false, headers = {} }) {
  return {
    http: { status, headers: { ...json, ...headers }, body },
    database: { accounts: accounts(from, to, ...(committed ? [fromVersion + 1, toVersion + 1] : [fromVersion, toVersion])), transaction: { committed } },
    messages,
    ordering,
    failures,
    retryability: retryable
  };
}

function fail(status, code, retryable) {
  return result({
    status, body: { error: code }, from: fromBalance, to: toBalance, committed: false,
    failures: [{ code, retryable }], retryable
  });
}

// Idempotent replay: key already processed -> return the stored outcome, no new event or state change.
const replays = input.processedKeys ?? input.idempotency ?? input.replays ?? {};
const prior = input.replay ?? input.existingTransfer ?? (idempotencyKey !== undefined ? replays[idempotencyKey] : undefined);
let out;
if (prior) {
  const b = prior.body ?? prior;
  const from = b.fromBalance ?? fromBalance;
  const to = b.toBalance ?? toBalance;
  out = {
    http: { status: 200, headers: { ...json, "idempotent-replay": "true" }, body: { transferId: b.transferId ?? transferId, fromBalance: from, toBalance: to, replayed: true } },
    database: { accounts: accounts(from, to, fromVersion, toVersion), transaction: { committed: false } },
    messages: [], ordering: [], failures: [], retryability: false
  };
} else if (!Number.isInteger(amount) || amount <= 0 || !fromId || !toId || fromId === toId) {
  out = fail(400, "invalid_request", false);
} else if (
  (input.currentFromVersion !== undefined && input.currentFromVersion !== fromVersion) ||
  (input.currentToVersion !== undefined && input.currentToVersion !== toVersion)
) {
  out = fail(409, "version_conflict", true);
} else if (fromBalance < amount) {
  out = fail(422, "insufficient_funds", false);
} else {
  const from = fromBalance - amount;
  const to = toBalance + amount;
  out = result({
    status: 200,
    body: { transferId, fromBalance: from, toBalance: to },
    from, to, committed: true,
    messages: [{ type: "transfer.completed", transferId, fromId, toId, amount }],
    ordering: ["debit", "credit", "commit", "publish"]
  });
}
console.log(JSON.stringify(out));
EOF
npm test 2>&1 | tail -8

